//! Parser for the global validation campaign dataset: ~2900 solar-position
//! test cases spanning the full input envelope requested for "validation
//! scientifique du modèle" (not just code validation against a handful of
//! hand-picked points): latitudes -90..+90°, longitudes -180..+180°,
//! altitudes 0..6000 m, years 1900..2100 (including the Gregorian
//! centennial leap-year exception), sunrise/sunset sweeps, polar day/night,
//! and near-subsolar cases.
//!
//! **Provenance**: generated by
//! `engine/validation-data/generate_global_campaign.py`, using the same
//! independent oracle as the smaller reference dataset in
//! [`crate::dataset`] — pvlib-python 0.15.2 (BSD-3-Clause), calling
//! `pvlib.spa`'s step-by-step functions directly. See
//! `engine/validation-data/README.md` for regeneration instructions.
//!
//! **Why CSV instead of a generated Rust array**: at ~2900 rows this
//! dataset would produce an unwieldy multi-megabyte generated `.rs` file
//! (the pattern used for the 91-case [`crate::dataset`]). Instead the CSV
//! is embedded as a `'static str` via `include_str!` and parsed once, at
//! first use, by the hand-rolled parser below — no dependency added (the
//! project's zero-dependency policy for the engine applies to this
//! validation crate too), and the committed CSV remains directly
//! inspectable and diffable.

use std::sync::LazyLock;

const CSV_DATA: &str = include_str!("../../../../validation-data/global_campaign_dataset.csv");

/// One case from the global validation campaign: inputs plus every expected
/// output quantity pvlib's SPA implementation computed for that input.
///
/// Field semantics are identical to [`crate::dataset::PvlibReferenceCase`]
/// (same generation pipeline, same pvlib functions called in the same
/// order) with the addition of [`GlobalCase::category`], which identifies
/// which envelope region (extreme latitude, polar night, sunrise sweep,
/// ...) a case belongs to, letting the evaluation report break statistics
/// down by category instead of only pooling everything together.
#[derive(Debug, Clone, Copy)]
pub struct GlobalCase {
    /// Which part of the input envelope this case was generated to cover
    /// (e.g. `"polar_night"`, `"century_years"`, `"sunrise_sunset_sweep"`).
    pub category: &'static str,
    /// Human-readable case identifier, unique within its category.
    pub label: &'static str,
    /// UTC calendar year (1900..=2100).
    pub year: i32,
    /// UTC calendar month, 1-12.
    pub month: u32,
    /// UTC calendar day of month.
    pub day: u32,
    /// UTC hour, 0-23.
    pub hour: u32,
    /// UTC minute, 0-59.
    pub minute: u32,
    /// UTC second (fractional).
    pub second: f64,
    /// Observer latitude, degrees, positive north (-90..=90).
    pub lat_deg: f64,
    /// Observer longitude, degrees, positive east (-180..=180).
    pub lon_deg: f64,
    /// Observer elevation, meters (0..=6000).
    pub elev_m: f64,
    /// Atmospheric pressure, pascals (ISO 2533:1975 standard atmosphere at
    /// `elev_m`).
    pub pressure_pa: f64,
    /// Ambient temperature, degrees Celsius.
    pub temperature_c: f64,
    /// delta_t = TT - UT1, seconds, specified exactly (not estimated) so
    /// every engine under test uses the same clock model pvlib was given —
    /// essential for years outside the 2005-2050 window where
    /// `core_math`'s own delta_t estimator is documented as invalid.
    pub delta_t_s: f64,
    /// Atmospheric refraction at the horizon, degrees.
    pub atmos_refract_deg: f64,
    /// Expected geocentric right ascension, degrees.
    pub expected_right_ascension_deg: f64,
    /// Expected geocentric declination, degrees.
    pub expected_declination_deg: f64,
    /// Expected equation of time, minutes.
    pub expected_equation_of_time_min: f64,
    /// Expected geocentric local hour angle, degrees.
    pub expected_hour_angle_deg: f64,
    /// Expected topocentric elevation without atmospheric refraction,
    /// degrees.
    pub expected_elevation_true_deg: f64,
    /// Expected topocentric elevation with atmospheric refraction, degrees.
    pub expected_elevation_apparent_deg: f64,
    /// Expected topocentric zenith without atmospheric refraction, degrees.
    pub expected_zenith_true_deg: f64,
    /// Expected topocentric zenith with atmospheric refraction, degrees.
    pub expected_zenith_apparent_deg: f64,
    /// Expected topocentric azimuth (from North, clockwise), degrees.
    pub expected_azimuth_deg: f64,
    /// Expected Earth-Sun distance, astronomical units.
    pub expected_earth_radius_vector_au: f64,
}

fn parse_field<T: std::str::FromStr>(fields: &[&'static str], index: usize, row: &str) -> T {
    fields[index].parse().unwrap_or_else(|_| {
        panic!(
            "global_campaign_dataset.csv row is malformed at field {index}: {row:?} \
             -- the committed CSV is a build-time invariant, not user input, so this is a bug in \
             generate_global_campaign.py or in the committed file, not a runtime condition to \
             recover from"
        )
    })
}

fn parse_row(row: &'static str) -> GlobalCase {
    let fields: Vec<&'static str> = row.split(',').collect();
    assert_eq!(
        fields.len(),
        25,
        "global_campaign_dataset.csv row has {} fields, expected 25: {row:?}",
        fields.len()
    );
    GlobalCase {
        category: fields[0],
        label: fields[1],
        year: parse_field(&fields, 2, row),
        month: parse_field(&fields, 3, row),
        day: parse_field(&fields, 4, row),
        hour: parse_field(&fields, 5, row),
        minute: parse_field(&fields, 6, row),
        second: parse_field(&fields, 7, row),
        lat_deg: parse_field(&fields, 8, row),
        lon_deg: parse_field(&fields, 9, row),
        elev_m: parse_field(&fields, 10, row),
        pressure_pa: parse_field(&fields, 11, row),
        temperature_c: parse_field(&fields, 12, row),
        delta_t_s: parse_field(&fields, 13, row),
        atmos_refract_deg: parse_field(&fields, 14, row),
        expected_right_ascension_deg: parse_field(&fields, 15, row),
        expected_declination_deg: parse_field(&fields, 16, row),
        expected_equation_of_time_min: parse_field(&fields, 17, row),
        expected_hour_angle_deg: parse_field(&fields, 18, row),
        expected_elevation_true_deg: parse_field(&fields, 19, row),
        expected_elevation_apparent_deg: parse_field(&fields, 20, row),
        expected_zenith_true_deg: parse_field(&fields, 21, row),
        expected_zenith_apparent_deg: parse_field(&fields, 22, row),
        expected_azimuth_deg: parse_field(&fields, 23, row),
        expected_earth_radius_vector_au: parse_field(&fields, 24, row),
    }
}

fn parse_dataset() -> Vec<GlobalCase> {
    let mut lines = CSV_DATA.lines();
    lines.next().expect("CSV header line must be present");
    lines.filter(|l| !l.is_empty()).map(parse_row).collect()
}

/// The full global campaign dataset, parsed once on first access from the
/// embedded CSV.
pub static DATASET: LazyLock<Vec<GlobalCase>> = LazyLock::new(parse_dataset);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dataset_parses_to_the_expected_case_count() {
        assert_eq!(DATASET.len(), 2918);
    }

    #[test]
    fn every_case_has_a_unique_label_within_its_category() {
        use std::collections::HashSet;
        let mut seen: HashSet<(&str, &str)> = HashSet::new();
        for case in DATASET.iter() {
            assert!(
                seen.insert((case.category, case.label)),
                "duplicate (category, label): ({}, {})",
                case.category,
                case.label
            );
        }
    }

    #[test]
    fn all_categories_from_the_generator_are_present() {
        let mut categories: Vec<&str> = DATASET.iter().map(|c| c.category).collect();
        categories.sort_unstable();
        categories.dedup();
        let expected = [
            "century_years",
            "extreme_altitude",
            "extreme_latitude",
            "extreme_longitude",
            "leap_years",
            "near_midnight_utc",
            "polar_day",
            "polar_night",
            "random_stratified",
            "subsolar_near_zenith",
            "sunrise_sunset_sweep",
        ];
        assert_eq!(categories, expected);
    }

    #[test]
    fn envelope_bounds_match_the_requested_specification() {
        for case in DATASET.iter() {
            assert!((-90.0..=90.0).contains(&case.lat_deg), "{case:?}");
            assert!((-180.0..=180.0).contains(&case.lon_deg), "{case:?}");
            assert!((0.0..=6000.0).contains(&case.elev_m), "{case:?}");
            assert!((1900..=2100).contains(&case.year), "{case:?}");
        }
    }
}
